const records = (queries.records && queries.records.data) || [];
return (data || []).map(u => {
  const items = records.filter(p => p.context === u.name).flatMap(p => Array.isArray(p.items) ? p.items : []);
  return {
    unit: u.name,
    owner: u.owner,
    scoped: items.length,
    pass: items.filter(t => t.status === 'Pass').length,
    open: items.filter(t => t.status === 'Fail' || t.status === 'Remediation ready').length,
    toTest: items.filter(t => t.status === 'Not tested').length
  };
});

return (data || []).flatMap(p => (Array.isArray(p.items) ? p.items : [])
  .filter(t => t.status === 'Fail' || t.status === 'Remediation ready')
  .map(t => ({ title: t.title, severity: t.severity || 'Medium', owner: t.owner, due: t.due, unit: p.context, engagement: p.name })));

const r = (data || [])[0];
return ((r && Array.isArray(r.history)) ? r.history : []).slice().reverse().map(h => ({
  event: h.event,
  note: h.note,
  at: String(h.at || '').slice(0, 16).replace('T', ' ')
}));
